const merchants = $input.all().map(i => i.json);
const counts = {};
const samples = {};
for (const m of merchants) {
  if (!m.mcc_code) continue;
  counts[m.mcc_code] = (counts[m.mcc_code] || 0) + 1;
  samples[m.mcc_code] = samples[m.mcc_code] || [];
  if (samples[m.mcc_code].length < 5) samples[m.mcc_code].push(m.name);
}
return Object.entries(counts).map(([mcc, count]) => ({
  mcc,
  account_count: count,
  top_accounts: samples[mcc]
}));

