// Loop over each high-risk merchant and stitch parallel branch findings together.
const merchants = $('Supabase: Get High-Risk Merchants').all().map(i => i.json);

return merchants.map((merchant, idx) => {
  const ofacByCompany = $('OpenSanctions: Company Screen').all()[idx]?.json    || {};
  const ofacByOwner   = $('OpenSanctions: Owner Screen').all()[idx]?.json   || {};
  const courtCompany  = $('CourtListener: Company Cases').all()[idx]?.json || {};
  const courtOwner    = $('CourtListener: Owner Cases').all()[idx]?.json   || {};
  const apifyRaw      = $('Apify: Google Reviews').all()[idx]?.json  || {};
  const adverseRaw    = $('Tavily: Adverse Media').all()[idx]?.json                         || {};
  const firecrawl     = $('Firecrawl: Scrape Merchant Site').all()[idx]?.json || {};
  const classify      = $('AI Agent: Classify Website').all()[idx]?.json?.output             || {};

  const allOfacResults = [
    ...(ofacByCompany.results || []).map(r => ({ ...r, queried_for: 'company' })),
    ...(ofacByOwner.results   || []).map(r => ({ ...r, queried_for: 'owner'   }))
  ];

  const place = apifyRaw.title
    ? apifyRaw
    : (Array.isArray(apifyRaw) ? apifyRaw[0] : {}) || {};
  const allReviews = place.reviews || [];
  const lowReviews = allReviews.filter(r => (r.stars || 5) <= 2);

  return {
    merchant_id: merchant.merchant_id,
    name: merchant.name,
    owner_name: merchant.owner_name,
    mcc: merchant.mcc,
    website: merchant.website,
    metrics: {
      cb_rate: merchant.cb_rate,
      refund_rate: merchant.refund_rate,
      exposure_score: merchant.exposure_score
    },
    ofac_pep_hits: allOfacResults.map(r => ({
      name: r.caption,
      datasets: r.datasets,
      score: r.score,
      queried_for: r.queried_for
    })),
    site_classification: classify,
    litigation_company: {
      count: courtCompany.count || 0,
      cases: (courtCompany.results || []).slice(0, 5).map(r => ({
        caseName: r.caseName, court: r.court, dateFiled: r.dateFiled
      }))
    },
    litigation_owner: {
      count: courtOwner.count || 0,
      cases: (courtOwner.results || []).slice(0, 5).map(r => ({
        caseName: r.caseName, court: r.court, dateFiled: r.dateFiled
      }))
    },
    google_reviews: {
      place_name: place.title,
      address: place.address,
      rating: place.totalScore,
      review_count: place.reviewsCount,
      negative_reviews: lowReviews.slice(0, 5).map(r => ({
        stars: r.stars, text: r.text, date: r.publishedAtDate
      }))
    },
    adverse_media: (adverseRaw.results || []).map(r => ({
      title: r.title, snippet: r.snippet, url: r.url, date: r.date
    })),
    findings_summary:
      `Merchant: ${merchant.name} (owner ${merchant.owner_name || 'unknown'}). ` +
      `MCC ${merchant.mcc}. CB rate ${merchant.cb_rate}. ` +
      `Risk score ${merchant.exposure_score}. ` +
      `Site vertical: ${classify.primary_vertical || 'unknown'}. ` +
      `Restricted verticals found: ${(classify.restricted_verticals_found || []).join(', ') || 'none'}. ` +
      `OFAC/PEP hits: ${allOfacResults.length} (company query: ${(ofacByCompany.results || []).length}, owner query: ${(ofacByOwner.results || []).length}). ` +
      `Litigation (company): ${courtCompany.count || 0}. ` +
      `Litigation (owner): ${courtOwner.count || 0}. ` +
      `Adverse media hits: ${(adverseRaw.results || []).length}.`
  };
});

