const rows = $input.all().map(i => i.json);
const byMonth = {};
for (const r of rows) {
  const m = r.month;
  if (!byMonth[m]) byMonth[m] = { vol: 0, cbCount: 0, refCount: 0, revCount: 0, merchantVol: 0 };
  byMonth[m].vol += (r.processing_vol || 0);
  byMonth[m].cbCount += ((r.cb_rate || 0) * (r.processing_vol || 0));
  byMonth[m].refCount += ((r.refund_rate || 0) * (r.processing_vol || 0));
  byMonth[m].revCount += ((r.reversal_rate || 0) * (r.processing_vol || 0));
  byMonth[m].merchantVol += (r.processing_vol || 0);
}
const series = Object.entries(byMonth).sort(([a],[b]) => a.localeCompare(b)).map(([m, v]) => ({
  month: m,
  total_processing_vol: v.vol,
  weighted_cb_rate: v.merchantVol > 0 ? v.cbCount / v.merchantVol : 0,
  weighted_refund_rate: v.merchantVol > 0 ? v.refCount / v.merchantVol : 0,
  weighted_reversal_rate: v.merchantVol > 0 ? v.revCount / v.merchantVol : 0
}));
const last = series[series.length - 1] || {};
const prev = series[series.length - 2] || {};
return [{
  series,
  current: last,
  prior: prev,
  deltas: {
    cb_rate: (last.weighted_cb_rate || 0) - (prev.weighted_cb_rate || 0),
    refund_rate: (last.weighted_refund_rate || 0) - (prev.weighted_refund_rate || 0),
    reversal_rate: (last.weighted_reversal_rate || 0) - (prev.weighted_reversal_rate || 0),
    processing_vol: (last.total_processing_vol || 0) - (prev.total_processing_vol || 0)
  }
}];

const mccAgg       = $('Aggregate MCC Snapshots').first()?.json || {};
const accountAgg   = $('Aggregate Account Findings').first()?.json || {};
const portfolio    = $('Supabase: Insert portfolio_snapshot').first()?.json || {};

const mccSnapshots       = mccAgg.mcc_snapshots || [];
const recommendedActions = accountAgg.recommended_actions || [];

return [{
  run_month:                $now.toFormat("yyyy-MM"),
  run_id:                   $execution.id,
  triggered_at:             $now.toISO(),
  generated_at:             new Date().toISOString(),
  status:                   'complete',
  mcc_snapshot_count:       mccSnapshots.length,
  recommended_action_count: recommendedActions.length,
  portfolio_snapshot_id:    portfolio.id
}];

