// Sentence-boundary truncation: cut at last complete sentence within the cap.
// If no sentence boundary found, return the full string (no '…' artifact).
// Auto-shrink in the deck handles visual fitting.
const truncSentence = (s, cap, hardMax) => {
  if (!s || typeof s !== 'string') return s || '';
  if (s.length <= cap) return s;
  // Look for sentence boundary in [0, cap]
  const slice = s.slice(0, cap);
  const lastDot = Math.max(slice.lastIndexOf('. '), slice.lastIndexOf('? '), slice.lastIndexOf('! '));
  if (lastDot > cap * 0.5) return slice.slice(0, lastDot + 1).trim();
  // No sentence boundary - return up to hardMax full string (no marker)
  return s.slice(0, hardMax || s.length);
};

// Trim a bullet to a word boundary, no marker
const trimBullet = (s, n) => {
  if (!s || typeof s !== 'string') return s || '';
  if (s.length <= n) return s;
  const slice = s.slice(0, n);
  const lastSpace = slice.lastIndexOf(' ');
  return (lastSpace > n * 0.7 ? slice.slice(0, lastSpace) : slice).trim();
};

const safeJson = (v) => {
  if (v == null) return v;
  if (typeof v === 'string') { try { return JSON.parse(v); } catch { return v; } }
  return v;
};

const month = $('Resolve Month').first().json.month;
const manifests   = $('Supabase: monthly_manifest').all().map(i => i.json);
const mccRaw      = $('Supabase: mcc_risk_snapshots').all().map(i => i.json);
const mccCodesRaw = $('Supabase: mcc_codes').all().map(i => i.json);
const actionsRaw  = $('Supabase: recommended_actions').all().map(i => i.json);
const portfolios  = $('Supabase: portfolio_snapshots').all().map(i => i.json);

const industryByCode = {};
for (const c of mccCodesRaw) {
  const code = String(c.code ?? c.mcc ?? '').trim();
  if (code) industryByCode[code] = c.industry || c.name || '';
}

const mcc_snapshots = mccRaw.map(m => {
  const codeKey = String(m.mcc ?? '').trim();
  return {
    mcc: m.mcc,
    industry: industryByCode[codeKey] || '',
    risk_rating: m.risk_rating,
    direction: m.direction,
    account_count: m.account_count,
    rec_action: m.rec_action,
    // Prefer sentence boundary, hard cap at 1100 if no boundary found - auto-shrink handles fit
    news_summary: truncSentence(m.news_summary || '', 700, 1100),
    top_accounts: (safeJson(m.top_accounts) || []).slice(0, 6),
    key_flags: (safeJson(m.key_flags) || []).slice(0, 3).map(f => ({
      category: f.category || '',
      headline: trimBullet(f.headline || '', 110)
    }))
  };
});
mcc_snapshots.sort((a, b) => (b.risk_rating || 0) - (a.risk_rating || 0));

const recommended_actions = actionsRaw.map(a => {
  const pp = safeJson(a.prior_precedent) || {};
  return {
    merchant_id: a.merchant_id,
    merchant_name: a.merchant_name,
    mcc: a.mcc,
    owner_name: a.owner_name,
    recommendation: a.recommendation,
    severity: a.severity,
    primary_drivers:  (safeJson(a.primary_drivers)  || []).slice(0, 3).map(d => trimBullet(d, 130)),
    policy_citations: (safeJson(a.policy_citations) || []).slice(0, 3).map(c => trimBullet(c, 130)),
    proposed_actions: (safeJson(a.proposed_actions) || []).slice(0, 3).map(p => trimBullet(p, 130)),
    prior_precedent: {
      found: pp.found ?? false,
      case_summary: truncSentence(pp.case_summary || '', 340, 500),
      outcome:      trimBullet(pp.outcome || '', 140)
    },
    reserve_change_bps: a.reserve_change_bps ?? 0,
    confidence: a.confidence,
    rationale: truncSentence(a.rationale || '', 700, 1100)
  };
});

const sevRank = { critical: 4, high: 3, medium: 2, low: 1 };
recommended_actions.sort((a, b) => (sevRank[b.severity] || 0) - (sevRank[a.severity] || 0));

const portfolio = portfolios[0] || null;
const portfolio_snapshot = portfolio ? {
  month: portfolio.month,
  total_merchants: portfolio.total_merchants,
  total_volume: portfolio.total_volume,
  avg_cb_rate: portfolio.avg_cb_rate,
  avg_refund_rate: portfolio.avg_refund_rate,
  high_risk_count: portfolio.high_risk_count,
  flagged_count: portfolio.flagged_count,
  trend_summary: truncSentence(portfolio.trend_summary || '', 600, 900)
} : null;

const recCounts = recommended_actions.reduce((acc, a) => {
  acc[a.recommendation] = (acc[a.recommendation] || 0) + 1;
  return acc;
}, {});

return [{
  month,
  fetched_at: new Date().toISOString(),
  manifest: manifests[0] || null,
  mcc_snapshots,
  recommended_actions,
  portfolio_snapshot,
  counts: {
    mcc_snapshots: mcc_snapshots.length,
    recommended_actions: recommended_actions.length,
    by_recommendation: recCounts,
    manifest_exists: manifests.length > 0,
    portfolio_exists: portfolios.length > 0,
    mcc_codes_loaded: mccCodesRaw.length
  }
}];
